      white-space: nowrap;
    }
    tbody td { padding: 10px 14px; border-bottom: 1px solid #f1f5f9; }
    tbody tr:last-child td { border-bottom: none; }
    tbody tr:hover { background: #fafbff; }

    /* ── RATING BAR ── */
    .rating-bar-wrap { display: flex; align-items: center; gap: 8px; }
    .rating-bar { height: 8px; border-radius: 4px; background: #e2e8f0; flex: 1; overflow: hidden; }
    .rating-bar-fill { height: 100%; border-radius: 4px; background: var(--primary-light); }
    .rating-pill {
