    .rec-card .rec-num { font-size: 11px; font-weight: 700; color: var(--primary); margin-bottom: 8px; text-transform: uppercase; letter-spacing: 1px; }
    .rec-card h4 { font-size: 14px; font-weight: 700; margin-bottom: 8px; }
    .rec-card p { font-size: 13px; color: var(--text-muted); line-height: 1.55; }
